import requests

base_url = "http://127.0.0.1:38847"
api_key = "arc-proxy"

# Try OPTIONS to discover available methods
headers = {"Authorization": f"Bearer {api_key}"}

print("Trying various HTTP methods on base URL:")
for method in ['GET', 'POST', 'PUT', 'DELETE', 'PATCH']:
    url = base_url
    try:
        if method == 'POST':
            response = requests.post(url, headers=headers, timeout=5)
        elif method == 'PUT':
            response = requests.put(url, headers=headers, timeout=5)
        else:
            response = requests.request(method, url, headers=headers, timeout=5)
        print(f"{method}: {response.status_code}")
    except Exception as e:
        print(f"{method}: Error - {type(e).__name__}")

